const env = vars.env || undefined, t = vars.table;
if (!/^[A-Za-z_][\w]*\.[A-Za-z_][\w]*$/.test(t)) throw new Error('table must be schema.table');
const found = await tools.pg_table({ name: t, env }), definition = Array.isArray(found) ? found[0] || {} : found; // one entry per database holding it
const count = await tools.pg_query({ env, sql: `select count(*) as rows from ${t} where ${vars.where}` });
const sample = await tools.pg_query({ env, sql: `select * from ${t} where ${vars.where}${vars.orderBy ? ` order by ${vars.orderBy}` : ''} limit ${Math.min(Number(vars.limit) || 20, 500)}` });
const usage = await tools.pg_usage({ name: t, env }).catch(e => ({ error: e.message }));
const rows = (count.preview || count.rows || [])[0]?.rows;
return { table: t, rows: rows === undefined ? null : Number(rows), columns: (definition.columns || []).map(c => `${c.name} ${c.type}${c.nullable === false ? ' not null' : ''}`), sample: sample.view, usedBy: (usage.rows || []).map(u => `${u.user} ${u.role}${u.where ? ' ' + u.where : ''}`), usage: usage.view };
